-- Explicit payment choices: either wallet pays the full 100; balances are never mixed.
update dy_private.account_config set document=jsonb_set(jsonb_set(document,'{character_themes}','[{"id": "dark-yeti", "title": "Dark Yeti", "version": 1, "avatar_id": "dark-yeti", "image": "https://www.drunkyetistudio.com/account/avatars/dark-yeti.webp", "entitlement": {"game_id": "yeti-account", "item_id": "avatar:dark-yeti"}, "palette": {"fur": "#27282D", "face": "#F2CC67"}, "description": "Unlock this avatar now. Includes ownership for matching Desktop Buddy skins and app/game themes as support is released.", "integrations": [{"surface": "account", "kind": "avatar", "status": "ready", "asset_id": "dark-yeti"}, {"surface": "desktop-buddy", "kind": "skin", "status": "planned"}, {"surface": "yeti-browser", "kind": "theme", "status": "planned"}, {"surface": "games", "kind": "theme", "status": "planned"}]}, {"id": "blush-yeti", "title": "Blush Yeti", "version": 1, "avatar_id": "blush-yeti", "image": "https://www.drunkyetistudio.com/account/avatars/blush-yeti.webp", "entitlement": {"game_id": "yeti-account", "item_id": "avatar:blush-yeti"}, "palette": {"fur": "#FADDE8", "face": "#F39A96"}, "description": "Unlock this avatar now. Includes ownership for matching Desktop Buddy skins and app/game themes as support is released.", "integrations": [{"surface": "account", "kind": "avatar", "status": "ready", "asset_id": "blush-yeti"}, {"surface": "desktop-buddy", "kind": "skin", "status": "planned"}, {"surface": "yeti-browser", "kind": "theme", "status": "planned"}, {"surface": "games", "kind": "theme", "status": "planned"}]}]'::jsonb),'{features,redemptions}','true'::jsonb) where id;
